<section class="section"><h1>Moderation Queue</h1><div class="card-list"><?php foreach ($flags as $flag): ?><article class="card"><h2><?= e($flag['recipe']['title'] ?? 'Missing recipe') ?></h2><p><strong>Reason:</strong> <?= e($flag['reason']) ?></p><p><strong>Reporter:</strong> <?= e($flag['reporter']['username'] ?? 'Unknown') ?></p><p><?= e($flag['details'] ?? '') ?></p><form action="/moderation/resolve" method="post" class="inline-form"><?= \App\Util\Csrf::field() ?><input type="hidden" name="flag_id" value="<?= e($flag['id']) ?>"><select name="action"><option value="approve">Approve</option><option value="block">Block</option><option value="delete">Soft delete</option></select><button class="button" type="submit">Resolve</button></form></article><?php endforeach; ?></div></section>
